INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL01',NULL,'1809.02472',NULL,'멀티로터 추력비','γ = T_hover/T_max','0.5','-','일반적인 멀티로터에서 선택하는 값(설계 선택값이지 물리 상수가 아님)',NULL,'paper','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL02',NULL,'1809.02472',NULL,'LiPo 배터리 팩','에너지밀도','140','Wh/kg','2018년 논문의 통계적 근사값. 현재 제품은 더 높을 수 있음',NULL,'paper','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL03',NULL,'1809.02472',NULL,'배터리 사용 가능 용량','사용 비율','0.85','-','과방전 방지용 15% 잔량',NULL,'paper','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL04',NULL,'1809.02472',NULL,'대기 밀도','ρ(고도, 온도)','ρ = 273/(273+Tt)·(1−0.0065·h/(273+Tt))^5.2561·ρ0, ρ0=1.293kg/m³(0°C)','kg/m³','국제표준대기(ISA) 모델. Tt는 °C, h는 m',NULL,'paper','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL05',NULL,'1809.02472',NULL,'ESC와 모터 정격','ESC 정격 ≥ 모터 최대','U_eMax ≥ U_mMax, I_eMax ≥ I_mMax','V, A','직렬 연결된 ESC·모터의 안전 조건. 논문 예시는 모터 최대 전류에 별도 안전 여유를 둠',NULL,'paper','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL06',NULL,'1809.02472',NULL,'멀티로터 질량 구성','추진계/배터리 비중','추진계 > 70%, 그중 배터리 > 60%','-','논문이 인용한 통계 모델([12]). 일반 멀티로터 기준, 페이로드 정의가 불분명',NULL,'paper','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL07',NULL,'1809.02472',NULL,'LiPo 셀 전압','충방전 범위와 환산 평균','4.2V → 3.7V, 환산 평균 4.0V/셀','V/cell','용량이 가득→소진으로 감소하는 범위',NULL,'paper','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL08',NULL,'2209.04128',NULL,'멀티로터 호버링 전력','P_hover = P_profile + (1+k)·W^1.5/√(2nρA)','유도 동력항 W^{3/2}/√(2nρA), 보정계수 k','W','n개 로터 합산. 논문의 시뮬레이션 값: k=0.11, δ=0.011, 솔리디티 s=0.045, ρ=1.168 (특정 기체 한 대의 값)',NULL,'paper','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL09',NULL,'2209.04128',NULL,'전진 비행 전력','전진 vs 호버 전력','대부분의 속도에서 호버보다 작고, 약 11m/s 이상에서 크게 증가','-','논문의 실험 기체 한 대, 고도 20m, 0~15m/s. 호버 약 317W',NULL,'paper','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL10',NULL,NULL,NULL,'수집 카탈로그의 팩 에너지밀도','Wh/kg = (mAh/1000·V_nom)/(kg)','전체 40개 중앙값 155, 300g 이상 28개 중앙값 163, 최소 90, 최대 311','Wh/kg','제조사 표기 무게·용량·공칭 전압으로 계산. 311·285는 대용량·저방전율 팩으로 특이값. 팩 무게에 케이블·커넥터 포함 여부는 제조사 표기에 따름',NULL,'manufacturer','sourced','medium',0,'derived',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL11',NULL,'2501.03102',NULL,'멀티로터 최적 전진 에너지','미터당 에너지(EPM)와 질량의 관계','최적 속도에서 EPM/m는 질량과 무관한 상수 → 최적 EPM은 질량에 비례','-','정속 전진 비행, 에너지 최적 속도에서만 성립. 임의 속도에서는 성립하지 않음. 1차 원리 모델 기반 해석·시뮬레이션',NULL,'paper','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL12',NULL,'2501.03102',NULL,'멀티로터 최적 순항 속도','v_opt와 질량의 관계','v_opt ∝ √m, 최적 피치각은 질량과 무관','-','CL11과 동일',NULL,'paper','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL13',NULL,'2306.07229',NULL,'MRS Drone 표준 기체 3종(4로터)','무게·프롭·배터리·비행시간','X500: 2.5kg/13in/199.8Wh/25분; F450: 1.7kg/9.4in/99.9Wh/15분; T650: 3.5kg/15in/177.6Wh/20분 (X500 풀센서 3.3kg은 20분)','-','논문 표의 값. 시험 조건(탑재물·바람·방전 종지)은 표에 명시되지 않음. 연구용 기체 한 그룹의 보고',NULL,'paper','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL14',NULL,NULL,'product-frame-holybro-x650-v2','Holybro X650 V2 (제조사)','키트 무게·프롭·배터리·공칭 호버 시간','키트 2000g(배터리 제외), 15인치 프롭(Gemfan 1555), 6S 10000mAh(1200g) 호버 30분(페이로드 없음), 축거 650mm','-','제조사 공칭값(낙관 방향). AUW는 키트+배터리≈3.2kg로 우리가 합산(FC 등 제외)',NULL,'manufacturer','sourced','medium',0,'derived',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL15',NULL,NULL,NULL,'호버 종합 효율 FM·η (역산)','이상 운동량 호버 전력 ÷ (배터리 Wh×DoD0.8 ÷ 보고 비행시간)','X500 0.35, F450 0.32, T650 0.45, X650(공칭) 0.47','-','n=4 (논문 3 + 제조사 1). 탑재물·바람·방전 종지 조건 불명이라 오차 방향이 불확실. 프롭 지름은 논문/제조사 표기값으로 원판 면적 계산',NULL,'derived','sourced','medium',0,'derived',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL16',NULL,'2607.22768',NULL,'리튬 배터리 팩 실효 에너지밀도','LiPo 팩 실효 비에너지 = 셀 비에너지 ÷ 패키징 계수 ηpkg','팩 실효 약 136~173Wh/kg (셀 180Wh/kg ÷ ηpkg 1.04~1.32, 나눗셈이며 곱하지 않음)','Wh/kg','MDO 엔진(AeroEval)의 모델 설정값(측정 아님). 셀 180Wh/kg·ηpkg 기준 1.04(대형), 4000mAh 미만 소형은 최대 +0.28까지 가산되어 1.32. 셀 180은 Table III에서 읽은 값',NULL,'paper','verified','medium',0,'model-assumption',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL17',NULL,'2607.22768',NULL,'설치 상태 호버 효율 저하','FoM_installed = FoM_isolated/κ','κ: 소비자 1.20, 기업용 1.25, 마이크로 1.30, 산업용 1.46','-','저자 모델 계수. FoM_max 값은 본문에서 찾지 못함',NULL,'paper','verified','medium',0,'model-assumption',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL18',NULL,'2607.22768',NULL,'기준 설계의 추력 대비 중량비','T/W (호버 스로틀 60% 기준)','2.78','-','저자 엔진의 기본 기준 실행(null role). 역할별로는 호버 스로틀 목표에 따라 달라짐',NULL,'paper','verified','medium',0,'model-assumption',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL19',NULL,'2607.22768',NULL,'탑재량 민감도(질량 눈덩이 효과)','dMTOW/dPayload','+1.692 kg/kg (비행시간 −1.703 min/kg)','kg/kg','저자 MDO 엔진의 시뮬레이션 결과(실측 아님). 나머지 파라미터 고정, COTS 이산 부품 매칭 포함',NULL,'paper','verified','medium',0,'simulation',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL20',NULL,'2607.22768',NULL,'전진 비행 전력','P_fwd(V) 최소점 V_md 존재, 25.5m/s 초과 시 발산','V_md = argmin P_fwd(V), 발산 속도 25.5','m/s','저자 모델(Glauert 유도속도 + 기생항력). Class 1 표준 구성',NULL,'paper','verified','medium',0,'model-assumption',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL21',NULL,'2607.22768',NULL,'모델 정확도 보고','MTOW 예측 MAPE','7.2% (상업용 19기종 블라인드), DIY 20기종 26.1%','%','저자가 보고한 검증. 상업용 19기종 377g~76kg',NULL,'paper','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL22',NULL,NULL,NULL,'비배터리·비페이로드 질량비(구조·추진·전장 합) 실측 역산','ef = 1 − 배터리비 − 페이로드비','페이로드 맞춤 배달 기체 0.42(2.57kg급)·0.29(24kg급); 페이로드 없는 범용 기체 F450 0.68·X500 0.56·T650 0.71·X650 0.63','-','배달 기체 값은 Zhang 2021 표를 P2604.07514가 인용한 2차 데이터. 범용 기체 값은 CL13·CL14의 총중량과 배터리 Wh(Wh/150 가정)에서 역산해 오차가 큼. 두 집단은 설계 목적이 다름(페이로드 맞춤 대 범용)',NULL,'derived','sourced','medium',0,'derived',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL23',NULL,NULL,NULL,'고정익·장시간 비행용 배터리 제조사 표기 비에너지','Wh/kg (제조사 사양 문구 표기)','23개 제품 265~450Wh/kg, 중앙값 330 (Molicel P50B 265, Tattu 반고체·UHV 팩 280~380, Amprius SiCore 450)','Wh/kg','제조사 공식 페이지에 인쇄된 값. 셀 단위/팩 단위가 제품마다 다르고(Amprius는 셀), 방전율 10C 이하 저전류 조건. 멀티로터 호버처럼 고방전율 용도의 실효값이 아님. 제조사 표기라 독립 검증 아님',NULL,'manufacturer','sourced','medium',0,'derived',NULL);
