INSERT INTO document_fts SELECT d.id, coalesce(d.domain,''), d.title, d.body, coalesce((SELECT group_concat(tag,' ') FROM (SELECT tag FROM document_tags t WHERE t.document_id=d.id ORDER BY tag)),'') FROM documents d ORDER BY d.id;
INSERT INTO claim_fts SELECT id, coalesce(subject_text,''), predicate, object_value, coalesce(conditions,'') FROM claims ORDER BY id;
